import 'package:flutter/material.dart';

class NoteHomePage extends StatefulWidget {
  @override
  _NoteHomePageState createState() => _NoteHomePageState();
}

class _NoteHomePageState extends State<NoteHomePage> {
  List<Note> notes = [];
  final titleController = TextEditingController();
  final contentController = TextEditingController();

  void addNote() {
    if (titleController.text.isNotEmpty && contentController.text.isNotEmpty) {
      setState(() {
        notes.add(
          Note(
            title: titleController.text,
            content: contentController.text,
          ),
        );
        titleController.clear();
        contentController.clear();
      });
    }
  }

  void deleteNote(int index) {
    setState(() {
      notes.removeAt(index);
    });
  }

  void toggleEdit(int index) {
    setState(() {
      notes[index].isEditing = !notes[index].isEditing;
    });
  }

  void updateNote(int index, String title, String content) {
    setState(() {
      notes[index].title = title;
      notes[index].content = content;
      notes[index].isEditing = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text('📝 My Notes'),
        backgroundColor: Colors.deepPurple,
      ),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          children: [
            TextField(
              controller: titleController,
              decoration: InputDecoration(labelText: 'Note Title'),
            ),
            SizedBox(height: 8),
            TextField(
              controller: contentController,
              decoration: InputDecoration(labelText: 'Note Content'),
              maxLines: 3,
            ),
            SizedBox(height: 10),
            ElevatedButton(
              onPressed: addNote,
              child: Text("Add Note"),
              style: ElevatedButton.styleFrom(backgroundColor: Colors.deepPurple),
            ),
            SizedBox(height: 20),
            Expanded(
              child: ListView.builder(
                itemCount: notes.length,
                itemBuilder: (context, index) {
                  final note = notes[index];
                  final titleEditCtrl = TextEditingController(text: note.title);
                  final contentEditCtrl = TextEditingController(text: note.content);

                  return Card(
                    margin: EdgeInsets.symmetric(vertical: 8),
                    child: Padding(
                      padding: const EdgeInsets.all(12),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          if (note.isEditing) ...[
                            TextField(
                              controller: titleEditCtrl,
                              decoration: InputDecoration(labelText: 'Edit Title'),
                            ),
                            SizedBox(height: 8),
                            TextField(
                              controller: contentEditCtrl,
                              decoration: InputDecoration(labelText: 'Edit Content'),
                              maxLines: 3,
                            ),
                            SizedBox(height: 8),
                            Row(
                              children: [
                                ElevatedButton(
                                  onPressed: () {
                                    updateNote(index, titleEditCtrl.text, contentEditCtrl.text);
                                  },
                                  child: Text("Save"),
                                ),
                                SizedBox(width: 8),
                                TextButton(
                                  onPressed: () => toggleEdit(index),
                                  child: Text("Cancel"),
                                ),
                              ],
                            )
                          ] else ...[
                            Text(note.title, style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold)),
                            SizedBox(height: 4),
                            Text(note.content),
                            Row(
                              mainAxisAlignment: MainAxisAlignment.end,
                              children: [
                                TextButton(
                                  onPressed: () => toggleEdit(index),
                                  child: Text("Edit"),
                                ),
                                TextButton(
                                  onPressed: () => deleteNote(index),
                                  child: Text("Delete", style: TextStyle(color: Colors.red)),
                                ),
                              ],
                            )
                          ]
                        ],
                      ),
                    ),
                  );
                },
              ),
            )
          ],
        ),
      ),
    );
  }
}
}
